INSERT INTO roles(codigo,nombre) VALUES ('ADMIN','Administrador'),('CERTIFICADOR','Certificador'),('FUSIONADOR','Fusionador'),('LECTURA','Lectura');
INSERT INTO permisos(codigo,descripcion) SELECT x,replace(initcap(x),'_',' ') FROM unnest(ARRAY[
INSERT INTO roles_permisos SELECT r.id,p.id FROM roles r CROSS JOIN permisos p WHERE r.codigo='ADMIN';
INSERT INTO roles_permisos SELECT r.id,p.id FROM roles r JOIN permisos p ON p.codigo LIKE 'CERTIFICACION_%' OR p.codigo LIKE 'MEDICION_%' WHERE r.codigo='CERTIFICADOR';
INSERT INTO roles_permisos SELECT r.id,p.id FROM roles r JOIN permisos p ON p.codigo LIKE 'FUSION_%' OR p.codigo IN ('PROYECTO_VER','CABECERA_VER','SECTOR_VER','DEPARTAMENTO_VER','PUERTO_VER','OPERADOR_VER','CABLE_VER','FIBRA_VER','FIBRA_ASIGNAR') WHERE r.codigo='FUSIONADOR';
INSERT INTO roles_permisos SELECT r.id,p.id FROM roles r JOIN permisos p ON p.codigo LIKE '%_VER' WHERE r.codigo='LECTURA';
